  it('creates a period budget and records a manually sourced exchange rate without trusting client totals',async()=>{await owner('patch',`members/${second.organizations[0]!.membership_id}`).send({role:'ACCOUNTANT',active:true}).expect(200);const budget=await owner('post','budgets').send({name:'Delivery allocation',projectId,amount:'100.000',currency:'OMR',startsAt:budgetStart,endsAt:budgetEnd}).expect(201);operatingBudget=budget.body.id;await owner('post','budgets').send({name:'Wrong base currency',amount:'1.00',currency:'USD',startsAt:budgetStart,endsAt:budgetEnd}).expect(400);const payload={title:'Converted delivery expense',projectId,budgetId:operatingBudget,currency:'USD',amount:'100.00',exchangeRate:'0.385',rateSource:'Manual test fixture, not a market quote',rateDate:new Date().toISOString(),expenseDate:new Date().toISOString(),approverId:second.organizations[0]!.membership_id};await endpoint('post',`organizations/${alphaOrg}/expenses`,employee,employeeCookie).send({...payload,baseAmount:'0.001'}).expect(400);await endpoint('post',`organizations/${alphaOrg}/expenses`,employee,employeeCookie).send({...payload,amount:'100.001'}).expect(400);await endpoint('post',`organizations/${alphaOrg}/expenses`,employee,employeeCookie).send({...payload,rateSource:''}).expect(400);const expense=await endpoint('post',`organizations/${alphaOrg}/expenses`,employee,employeeCookie).send(payload).expect(201);convertedExpense=expense.body.id;expect(expense.body.amount).toBe('100.00');expect(expense.body.baseAmount).toBe('38.500');expect(expense.body.rateSource).toBe(payload.rateSource);await endpoint('get',`organizations/${alphaOrg}/expenses/${convertedExpense}`,beta,betaCookie).expect(403);await endpoint('get',`organizations/${alphaOrg}/budgets/${operatingBudget}`,employee,employeeCookie).expect(403);});
