  it('preserves approved expenses and reverses their effect only with explicit reversal authority',async()=>{const budget=await owner('get',`budgets/${operatingBudget}`).expect(200);await owner('patch',`budgets/${operatingBudget}`).send({name:budget.body.name,projectId,amount:'50.000',startsAt:budgetStart,endsAt:budgetEnd,version:budget.body.version}).expect(400);await owner('patch',`budgets/${operatingBudget}`).send({name:budget.body.name,projectId,amount:'120.000',startsAt:budgetStart,endsAt:budgetEnd,version:budget.body.version}).expect(200);await expenseAction(overrunExpense,'REVERSE',second,secondCookie,403);await expenseAction(overrunExpense,'REVERSE',alpha,alphaCookie);const after=await owner('get',`budgets/${operatingBudget}`).expect(200);expect(after.body.spent).toBe('38.500');expect(after.body.remaining).toBe('81.500');expect(await admin.operationalExpense.count({where:{id:overrunExpense,status:'REVERSED'}})).toBe(1);expect(await admin.expenseEvent.count({where:{expenseId:overrunExpense,action:'REVERSE'}})).toBe(1);});
