  it('searches actual Arabic and English work while preserving module permissions, privacy and tenant isolation',async()=>{const title='بحث متكامل SearchScope '+suffix;const mine=(await owner('post','tasks').send({title:title+' owner',visibility:'PRIVATE'}).expect(201)).body;const theirs=(await endpoint('post',`organizations/${alphaOrg}/tasks`,employee,employeeCookie).send({title:title+' employee',visibility:'PRIVATE'}).expect(201)).body;const other=(await endpoint('post',`organizations/${betaOrg}/tasks`,beta,betaCookie).send({title:title+' other tenant',visibility:'PRIVATE'}).expect(201)).body;const own=await owner('get','search').query({q:'SearchScope',kind:'tasks'}).expect(200);expect(own.body.total).toBe(2);expect(own.body.groups[0].items.map((row:{id:string})=>row.id)).toEqual(expect.arrayContaining([mine.id,theirs.id]));expect(JSON.stringify(own.body)).not.toContain(other.id);const limited=await endpoint('get',`organizations/${alphaOrg}/search`,employee,employeeCookie).query({q:'بحث متكامل'}).expect(200);expect(limited.body.groups.find((group:{kind:string})=>group.kind==='tasks').items.map((row:{id:string})=>row.id)).toEqual([theirs.id]);expect(JSON.stringify(limited.body)).not.toContain(mine.id);expect(limited.body.groups.some((group:{kind:string})=>group.kind==='workflows'||group.kind==='budgets')).toBe(false);await endpoint('get',`organizations/${alphaOrg}/search`,beta,betaCookie).query({q:'SearchScope'}).expect(403);const byNumber=await owner('get','search').query({q:mine.number,kind:'tasks'}).expect(200);expect(byNumber.body.groups[0].items[0].id).toBe(mine.id);const page1=await owner('get','search').query({q:'SearchScope',kind:'tasks',pageSize:1,page:1}).expect(200);const page2=await owner('get','search').query({q:'SearchScope',kind:'tasks',pageSize:1,page:2}).expect(200);expect(page1.body.groups[0].items[0].id).not.toBe(page2.body.groups[0].items[0].id);await owner('get','search').query({q:'x'}).expect(400);await owner('get','search').query({q:'%_',kind:'tasks'}).expect(200).then(result=>expect(result.body.total).toBe(0));await owner('delete',`tasks/${mine.id}`).expect(200);const archived=await owner('get','search').query({q:'SearchScope',kind:'tasks'}).expect(200);expect(archived.body.total).toBe(1);});
  it('reports exact filtered aggregates and period comparisons with independent scoped report permissions',async()=>{const member=alpha.organizations.find(row=>row.id===alphaOrg)!.membership_id,staff=employee.organizations.find(row=>row.id===alphaOrg)!.membership_id;const from='2025-03-01T00:00:00Z',to='2025-04-01T00:00:00Z';const make=async(title:string,assignedToId:string,hours:string,status:string,createdAt:string)=>{const row=(await owner('post','tasks').send({title,assignedToId,visibility:'PRIVATE',estimatedHours:hours,dueDate:createdAt.startsWith('2025-02')?'2025-02-20T00:00:00Z':'2025-03-20T00:00:00Z'}).expect(201)).body;await admin.task.update({where:{id:row.id},data:{status,createdAt:new Date(createdAt),completedAt:status==='COMPLETED'?new Date('2025-03-15T00:00:00Z'):null}});return row;};const done=await make('Report completed fixture',member,'2.50','COMPLETED','2025-03-10T00:00:00Z');const pending=await make('Report pending fixture',staff,'3.75','IN_PROGRESS','2025-03-11T00:00:00Z');await make('Report cancelled fixture',member,'1.00','CANCELLED','2025-03-12T00:00:00Z');await make('Report comparison fixture',member,'4.00','OPEN','2025-02-10T00:00:00Z');const result=await owner('get','reports').query({kind:'tasks',from,to,compare:'true'}).expect(200);expect(result.body.summary).toMatchObject({tasks:3,completed:1,overdue:1,estimatedHours:'7.25'});expect(result.body.previous.summary.tasks).toBe(1);expect(result.body.total).toBe(3);const complete=await owner('get','reports').query({kind:'completion',from,to}).expect(200);expect(complete.body.items.map((row:{id:string})=>row.id)).toEqual([done.id]);const load=await owner('get','reports').query({kind:'workload',from,to}).expect(200);expect(load.body.items).toMatchObject([{tasks:1,estimatedHours:'3.75'}]);const late=await owner('get','reports').query({kind:'delays',from,to}).expect(200);expect(late.body.items.map((row:{id:string})=>row.id)).toEqual([pending.id]);await endpoint('get',`organizations/${alphaOrg}/reports`,employee,employeeCookie).query({kind:'tasks',from,to}).expect(403);const role=await owner('post','roles').send({name:'Scoped report reader',permissions:['reports.read']}).expect(201),assignment=await owner('post','role-assignments').send({membershipId:staff,roleId:role.body.id,scope:'OWN'}).expect(201);try{const own=await endpoint('get',`organizations/${alphaOrg}/reports`,employee,employeeCookie).query({kind:'tasks',from,to}).expect(200);expect(own.body.summary.tasks).toBe(1);expect(own.body.items.map((row:{id:string})=>row.id)).toEqual([pending.id]);await endpoint('post',`organizations/${alphaOrg}/reports/export`,employee,employeeCookie).send({query:{kind:'tasks',from,to},format:'csv'}).expect(403);await endpoint('get',`organizations/${alphaOrg}/reports`,beta,betaCookie).query({kind:'tasks',from,to}).expect(403);}finally{await owner('delete',`role-assignments/${assignment.body.id}`).expect(200);await owner('delete',`roles/${role.body.id}`).expect(200);}for(const kind of ['employees','departments','projects','budgets','expenses','time','meetings','approvals','automation']){const report=await owner('get','reports').query({kind}).expect(200);expect(report.body.columns.length).toBeGreaterThan(0);expect(report.body.total).toBeGreaterThanOrEqual(report.body.items.length);}await owner('get','reports').query({kind:'budgets',priority:'HIGH'}).expect(400);await owner('get','reports').query({kind:'tasks',compare:'true'}).expect(400);});
  it('exports permission-filtered XLSX, formula-safe CSV and a real Arabic PDF',async()=>{const title='=HYPERLINK("https://example.invalid","literal")';const source=(await owner('post','tasks').send({title,visibility:'PRIVATE'}).expect(201)).body;await admin.task.update({where:{id:source.id},data:{createdAt:new Date('2024-01-10T00:00:00Z')}});const query={kind:'tasks',from:'2024-01-01T00:00:00Z',to:'2024-02-01T00:00:00Z'};const binary=(res:request.Response,callback:(error:Error|null,body:Buffer|null)=>void)=>{const chunks:Buffer[]=[];res.on('data',(chunk:Buffer)=>chunks.push(chunk));res.on('end',()=>callback(null,Buffer.concat(chunks)));res.on('error',(error:Error)=>callback(error,null));};const csv=await owner('post','reports/export').send({query,format:'csv',locale:'en'}).expect(201).expect('Content-Type',/^text.csv/);expect(csv.text).toContain(`"'=HYPERLINK(""https://example.invalid"",""literal"")"`);const file=await owner('post','reports/export').send({query,format:'xlsx',locale:'en'}).buffer(true).parse(binary).expect(201).expect('Cache-Control','no-store');const {Workbook}=require('exceljs');const workbook=new Workbook();await workbook.xlsx.load(file.body);const sheet=workbook.getWorksheet('Tasks');expect(sheet.rowCount).toBe(2);expect(sheet.getCell('B2').value).toBe(title);expect(sheet.getCell('B2').type).toBe(3);const pdf=await owner('post','reports/export').send({query,format:'pdf',locale:'ar'}).buffer(true).parse(binary).expect(201).expect('Content-Type',/^application.pdf/);expect(pdf.body.subarray(0,5).toString()).toBe('%PDF-');expect(pdf.body.length).toBeGreaterThan(5000);expect(await admin.auditLog.count({where:{organizationId:alphaOrg,resourceType:'report_tasks',action:'REPORT_EXPORT_REQUESTED'}})).toBeGreaterThanOrEqual(3);});
